root.querySelector('[data-report-print]').onclick=()=>{const win=window.open('','_blank');if(!win){alert('Permita abrir a janela de impressão.');return}win.document.open();win.document.write(reportDocument(reportRows()));win.document.close();win.focus();win.print()};
